  const foodLibrary=document.createElement('section');foodLibrary.className='diet-food-library';foodLibrary.innerHTML='<header><div><strong>🧺 Biblioteca de alimentos</strong><small>Pesquise, filtre e selecione alimentos para inserir em um clique.</small></div><button type="button" data-fl-toggle>＋ Abrir biblioteca</button></header><div data-fl-body hidden><div class="diet-food-filters"><input type="search" data-fl-search placeholder="🔎 Buscar alimento..."><select data-fl-cat><option>Todos</option><option>Carboidratos</option><option>Proteínas</option><option>Frutas</option><option>Vegetais</option><option>Gorduras</option><option>Leguminosas</option></select></div><div class="diet-food-grid" data-fl-grid></div><footer><span data-fl-count>0 selecionados</span><button type="button" data-fl-add>Adicionar selecionados à refeição</button></footer></div>';toolsBar.after(foodLibrary);
